     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main id="main-content" class="page-shell">
       <div id="support-contact-root"></div>
     </main>

     <script>
       const formFields = [
         {
           id: "full-name",
           name: "fullName",
           label: "Full name",
           type: "text",
           required: true,
           autocomplete: "name",
           error: "Error: Enter your full name."
         },
         {
           id: "email-address",
           name: "email",
           label: "Email address",
           type: "email",
           required: true,
           autocomplete: "email",
           error: "Error: Enter a valid email address, such as name@example.com."
         },
         {
           id: "phone-number",
           name: "phone",
           label: "Phone number",
           type: "tel",
           required: false,
           autocomplete: "tel",
           help: "Use digits, spaces, dashes, or parentheses; for example, (555) 123-4567."
         }
       ];

       function Field({ id, name, label, type, required, autocomplete, help }) {
         const helpId = help ? `${id}-help` : "";
         const describedBy = helpId ? ` aria-describedby="${helpId}"` : "";
         const requiredText = required
           ? ' <span class="required-marker" aria-hidden="true">*</span>'
           : ' <span class="optional-text">(optional)</span>';

         return `
           <div class="form-field">
             <label for="${id}">${label}${requiredText}</label>
             <input
               id="${id}"
               name="${name}"
               type="${type}"
               autocomplete="${autocomplete}"
               ${required ? "required" : ""}
               ${describedBy}
             >
             ${help ? `<p class="field-help" id="${helpId}">${help}</p>` : ""}
           </div>
         `;
       }

       function SupportContactForm() {
         return `
           <section class="support-card" aria-labelledby="support-title">
             <div class="support-intro">
               <div>
                 <p class="eyebrow">Support</p>
                 <h1 id="support-title">How can we help?</h1>
                 <p class="intro-copy">
                   Tell us how to reach you and our support team will follow up with practical next steps.
                 </p>
               </div>
               <p class="support-note">
                 We usually reply within one business day. Phone is optional, but it can help us resolve urgent issues faster.
               </p>
             </div>
             <div class="form-panel">
               <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required fields</p>
               <form id="support-form" novalidate>
                 ${formFields.map(Field).join("")}
                 <div class="submit-row">
                   <button type="submit">Send request</button>
                   <p class="form-status" id="form-status" aria-live="polite"></p>
                 </div>
               </form>
             </div>
           </section>
         `;
       }

       function validateField(input) {
         const field = formFields.find((item) => item.id === input.id);
         if (!field || !field.required) {
           return "";
         }

         if (!input.value.trim()) {
           return field.error;
         }

         if (input.type === "email" && !input.validity.valid) {
           return field.error;
         }

         return "";
       }

       function setFieldError(input, message) {
         const existingError = document.getElementById(`${input.id}-error`);
         const helpId = document.getElementById(`${input.id}-help`) ? `${input.id}-help` : "";

         if (existingError) {
           existingError.remove();
         }

         if (!message) {
           input.removeAttribute("aria-invalid");
           input.removeAttribute("aria-errormessage");
           if (helpId) {
             input.setAttribute("aria-describedby", helpId);
           } else {
             input.removeAttribute("aria-describedby");
           }
           return;
         }

         const errorId = `${input.id}-error`;
         const error = document.createElement("p");
         error.className = "field-error";
         error.id = errorId;
         error.textContent = message;
         input.insertAdjacentElement("afterend", error);
         input.setAttribute("aria-invalid", "true");
         input.setAttribute("aria-errormessage", errorId);
         input.setAttribute("aria-describedby", [helpId, errorId].filter(Boolean).join(" "));
       }

       function attachFormBehavior() {
         const form = document.getElementById("support-form");
         const status = document.getElementById("form-status");

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           status.textContent = "";
           status.classList.remove("success");

           const inputs = Array.from(form.querySelectorAll("input"));
           const invalidInputs = [];

           inputs.forEach((input) => {
             const message = validateField(input);
             setFieldError(input, message);
             if (message) {
               invalidInputs.push(input);
             }
           });

           if (invalidInputs.length > 0) {
             status.textContent = "Please fix the highlighted fields.";
             invalidInputs[0].focus();
             return;
           }

           status.textContent = "Thanks. Your support request is ready to send.";
           status.classList.add("success");
           form.reset();
         });

         form.addEventListener("input", (event) => {
           if (event.target instanceof HTMLInputElement && event.target.getAttribute("aria-invalid") === "true") {
             setFieldError(event.target, validateField(event.target));
           }
         });
       }

       document.getElementById("support-contact-root").innerHTML = SupportContactForm();
       attachFormBehavior();
     </script>
   </body>
 </html>
